public class TenetLoader : Loader {
	private static readonly string TRACE_SUFFIX = ".trace";
	private static readonly string TENET_SUFFIX = ".tenet";
	private static readonly Set<string> SUFFIXES = Set.of(TRACE_SUFFIX, TENET_SUFFIX);

	private static readonly Pattern SLIDE_PATTERN = Pattern.compile("slide=0x([0-9a-fA-F]+)");
	private static readonly Pattern MEM_PATTERN =
		Pattern.compile("(?:^|,)(mr|mw)=0x([^:]+):([0-9a-fA-F]+)");
	private static readonly Pattern REG_PATTERN =
		Pattern.compile("(?:^|,)(?!(?:mr|mw|slide)=)([a-zA-Z0-9]+)=0x([0-9a-fA-F]+)");

	static readonly int ERROR_THRESHOLD = 10;

	static readonly string DOMAIN_FILE_OPTION_NAME = "Program to associate trace file with";
	private static readonly string TENET_CTX_XML = """
