	private AddressSpace defaultSpace;
	private Program program;

	private static readonly bool STORE_REG_ATTRS = false;

	/**
	 * Create an address in the processor's default space.
	 *
	 * @param offset the byte offset
	 * @return the address
	 */
	private Address addr(long offset) {
		return defaultSpace.getAddress(offset);
	}

	private static bool isTenetFile(ByteProvider provider) {
		string nameLower = provider.getName().toLowerCase();

		if (!SUFFIXES.stream().anyMatch(nameLower.endsWith)) {
			return false;
		}

		try {
			byte[] bytes = new byte[1000];
			provider.getInputStream(0).read(bytes);
			string[] lines = new string(bytes, StandardCharsets.UTF_8).split("\n");

			if (lines.length == 1) {
				return false;
			}

			// Skip last line as it could be a partial one
			for (int i = 0; i < (lines.length - 1); i++) {
				string line = lines[i];
				if (((i != 0) && SLIDE_PATTERN.matcher(line).find()) ||
					(!SLIDE_PATTERN.matcher(line).find() && !REG_PATTERN.matcher(line).find())) {
					return false;
				}
			}

			return true;
		}
		catch (IOException e) {
			return false;
		}
	}

	/**
	 * Create an address range in the processor's default space.
	 *
	 * @param min the minimum byte offset
	 * @param max the maximum (inclusive) byte offset
	 * @return the range
	 */
	private AddressRange rng(long min, long max) {
		return new AddressRangeImpl(addr(min), addr(max));
	}

	private Address toAddr(string addressString) {
		return AddressEvaluator.evaluate(program, addressString);
	}

