	private Trace loadTrace(ByteProvider provider, string name, Program program,
			object consumer, MessageLog log, TaskMonitor monitor)
    {

		this.program = program;
		Language lang = program.getLanguage();
		this.defaultSpace = lang.getAddressFactory().getDefaultAddressSpace();

		Trace trace = new DBTrace(name, program.getCompilerSpec(), consumer);
		TraceObjectManager om = trace.getObjectManager();

		try
{
    using (Transaction tx = trace.openTransaction("Import Tenet Trace: %s".formatted(name)))
    using (BypassWriteCache bypass = om.withoutWriteCache())
    {


			om.createRootObject(TENET_SESSION_SCHEMA);

			TraceThread traceThread =
				trace.getThreadManager().createThread("Thread", "Thread", 0);

			trace.getObjectManager()
					.createObject(KeyPath.parse("Breakpoints"))
					.insert(Lifespan.ALL, ConflictResolution.DENY);

			Pattern ipPattern = Pattern.compile(
				"(?:^|,)%s=0x([0-9a-fA-F]+)".formatted(lang.getProgramCounter().getName()),
				Pattern.CASE_INSENSITIVE);

			BufferedReader lineCounter = new BufferedReader(
				new InputStreamReader(provider.getInputStream(0), StandardCharsets.UTF_8));
			long numLines = lineCounter.lines().count();
			lineCounter.close();
			monitor.setMaximum(numLines);

			try (BufferedReader reader = new BufferedReader(
				new InputStreamReader(provider.getInputStream(0), StandardCharsets.UTF_8))) {
				string line = reader.readLine();
				long slideValue = 0;
				long curIp = 0;
				Matcher slideMatcher = SLIDE_PATTERN.matcher(line);
				int lineNumber = 1;
				int errorCount = 0;
				int snapNumber = 0;

				if (slideMatcher.find()) {
					slideValue = Long.parseLong(slideMatcher.group(1), 16);
					lineNumber++;
					line = reader.readLine();
				}

				TraceSnapshot snapshot =
					trace.getTimeManager().createSnapshot("Snapshot %d".formatted(snapNumber));
				snapshot.setEventThread(traceThread);
				long snap = snapshot.getKey();

				snapNumber++;

				setupMemoryAndMapping(program, trace, slideValue, snap);

				try {
					while (line != null) {
						monitor.checkCancelled();

						if (errorCount >= ERROR_THRESHOLD) {
							throw new LoadException("Encountered too many errors with this trace");
						}

						Matcher ipMatcher = ipPattern.matcher(line);
						if (ipMatcher.find()) {
							curIp = Long.parseLong(ipMatcher.group(1), 16);

							if (parseRegisterOperations(snap, curIp, line, lineNumber, traceThread,
								trace, log, monitor)) {
								parseMemoryOperations(snap, curIp, line, trace, monitor);
							}
							else {
								errorCount++;
							}
						}
						else {
							log.appendMsg(
								"Line %d: Unable to find PC, skipping...".formatted(lineNumber));
							errorCount++;
						}

						lineNumber++;
						monitor.setProgress(lineNumber);

						line = reader.readLine();
						if (line != null) {
							snapshot = trace.getTimeManager()
									.createSnapshot("Snapshot %d".formatted(snapNumber));
							snap = snapshot.getKey();
							snapshot.setEventThread(traceThread);
							snapNumber++;
						}
					}
				}
				catch (CancelledException e) {
					throw e;
				}
				catch (Exception e) {
					throw new LoadException(e);
				}
			}
		
    }
}
		catch (Exception e) when (e is TraceOverlappedRegionException or DuplicateNameException) {
			// This should not happen
			throw new AssertionError(e);
		}
		return trace;
	}

	private void parseMemoryOperations(long snap, long curIp, string line,
			Trace trace, TaskMonitor monitor)
    {

		Matcher memMatcher = MEM_PATTERN.matcher(line);

		// TODO Speed this up
		while (memMatcher.find()) {
			monitor.checkCancelled();
			RefType refType = memMatcher.group(1).equals("mr") ? RefType.READ : RefType.WRITE;
			Address address = toAddr(memMatcher.group(2));
			byte[] bytes = NumericUtilities.convertStringToBytes(memMatcher.group(3));

			trace.getReferenceManager()
					.addMemoryReference(Lifespan.at(snap), addr(curIp),
						new AddressRangeImpl(address, bytes.length), refType, SourceType.IMPORTED,
						-1);
			trace.getMemoryManager().putBytes(snap, address, ByteBuffer.wrap(bytes));
		}
	}

	private bool parseRegisterOperations(long snap, long curIp, string line,
			int lineNumber, TraceThread traceThread, Trace trace,
			MessageLog log, TaskMonitor monitor)
    {
		TraceStackFrame frame =
			trace.getStackManager().getStack(traceThread, snap, true).getFrame(snap, 0, true);
		frame.setProgramCounter(Lifespan.nowOn(snap), addr(curIp));

		KeyPath traceRegistersPath = frame.getObject().getCanonicalPath().extend("Registers");
		TraceObject traceRegisters =
			trace.getObjectManager().createObject(traceRegistersPath);
		traceRegisters.insert(Lifespan.ALL, ConflictResolution.DENY);

		Matcher regMatcher = REG_PATTERN.matcher(line);
		while (regMatcher.find()) {
			monitor.checkCancelled();

			BigInteger val = new BigInteger(regMatcher.group(2), 16);
			Register regObj = trace.getProgramView().getRegister(regMatcher.group(1));
			if (regObj == null) {
				log.appendMsg("Line %d: Register %s not found in program language!"
						.formatted(lineNumber, regMatcher.group(1)));
				return false;
			}

			if (STORE_REG_ATTRS) {
				traceRegisters.setElement(Lifespan.nowOn(snap), regObj.getName(), val.longValue());
			}
			trace.getMemoryManager()
					.getMemoryRegisterSpace(frame, true)
					.setValue(snap, new RegisterValue(regObj, val));
		}
		return true;
	}

	private void setupMemoryAndMapping(Program program, Trace trace,
			long slideValue, long snap)
    {
		TraceModuleManager modMan = trace.getModuleManager();
		TraceStaticMappingManager mapMan = trace.getStaticMappingManager();
		URL projectUrl = program.getDomainFile().getLocalProjectURL("");

		if (slideValue != 0) {
			Msg.info(this, "Adding slide %x".formatted(slideValue));
			mapMan.add(rng(slideValue, slideValue + program.getMemory().getSize()),
				Lifespan.nowOn(snap), projectUrl, "ram:%s".formatted(program.getImageBase()));
			modMan.addLoadedModule("Modules[%s]".formatted(program.getName()),
				program.getExecutablePath(),
				rng(slideValue, slideValue + program.getMemory().getSize()), snap);
		}
		else {
			mapMan.add(
				rng(program.getImageBase().getUnsignedOffset(),
					program.getImageBase().add(program.getMemory().getSize()).getUnsignedOffset()),
				Lifespan.nowOn(snap), projectUrl, "ram:%s".formatted(program.getImageBase()));
			modMan.addLoadedModule("Modules[%s]".formatted(program.getName()),
				program.getExecutablePath(),
				rng(program.getImageBase().getUnsignedOffset(), program.getMemory().getSize()),
				snap);
		}

		// Add one giant memory region
		// TODO: Maybe make this more accurate in the future through
		// some analysis?
		trace.getMemoryManager()
				.addRegion("Memory[ALL]", Lifespan.nowOn(0), rng(0x0, 0xFFFF_FFFF_FFFF_FFFFL),
					TraceMemoryFlag.READ, TraceMemoryFlag.EXECUTE, TraceMemoryFlag.WRITE);
	}

	/* @Override */
	public string validateOptions(ByteProvider provider, LoadSpec loadSpec,
			List<Option> options, Program program) {
		if (options != null) {
			foreach (Option option in options) {
				string name = option.getName();
				if (name.equals(DOMAIN_FILE_OPTION_NAME) &&
					!typeof(string).isAssignableFrom(option.getValueClass())) {
					return "Invalid type for option: " + name + " - " + option.getValueClass();
				}
			}
		}
		return null;
	}
